package com.jnapanam.sportszone.tournament.controller;import com.jnapanam.sportszone.tournament.dto.*;import com.jnapanam.sportszone.tournament.service.TournamentService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/tournaments")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public class AdminTournamentController{private final TournamentService service;public AdminTournamentController(TournamentService s){service=s;}@GetMapping public List<TournamentResponse>all(){return service.all();}@PostMapping@ResponseStatus(HttpStatus.CREATED)public TournamentResponse create(@Valid@RequestBody TournamentRequest r){return service.create(r);}@PutMapping("/{id}")public TournamentResponse update(@PathVariable UUID id,@Valid@RequestBody TournamentRequest r){return service.update(id,r);}@PatchMapping("/{id}/status")public TournamentResponse status(@PathVariable UUID id,@Valid@RequestBody TournamentStatusRequest r){return service.status(id,r);}@GetMapping("/{id}/teams")public List<TeamResponse>teams(@PathVariable UUID id){return service.teams(id);}@PostMapping("/{id}/fixtures/generate")public List<FixtureResponse>generate(@PathVariable UUID id){return service.generate(id);}@PatchMapping("/fixtures/{id}/schedule")public FixtureResponse schedule(@PathVariable UUID id,@RequestBody FixtureScheduleRequest r){return service.schedule(id,r);}@PatchMapping("/fixtures/{id}/result")public FixtureResponse result(@PathVariable UUID id,@Valid@RequestBody FixtureResultRequest r){return service.result(id,r);}@GetMapping("/organizer-applications/approved")public List<OrganizerApplicationResponse>approved(){return service.approvedOrganizers();}@GetMapping("/organizer-applications")public List<OrganizerApplicationResponse>applications(){return service.applications();}@PatchMapping("/organizer-applications/{id}")public OrganizerApplicationResponse review(@PathVariable UUID id,@Valid@RequestBody OrganizerReviewRequest r){return service.review(id,r);}}
